/* Both completed species together; hover summaries use native historical data. */
(()=>{
 'use strict';
 const $=id=>document.getElementById(id),colours={longissima:'#267d6f',japonica:'#8b557e'},names={longissima:'S. longissima',japonica:'S. japonica'};
 const tr=(en,ar=en,ja=en)=>PortalLanguage.current==='ar'?ar:PortalLanguage.current==='ja'?ja:en;
 let spaces={},histories={},points,areas,habitatRenderer,gridRenderer,loaded=false,serial=0;
 async function gzip(path){const r=await fetch(path);if(!r.ok)throw Error('Map history unavailable');return JSON.parse(await new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).text());}
 function mini(years,values,label,unit,color){const w=310,h=95,left=45,right=10,top=10,bottom=22,valid=values.filter(Number.isFinite);if(!valid.length)return '';let low=Math.min(...valid),high=Math.max(...valid);if(high===low){low=Math.max(0,low-1);high+=1;}const x=i=>left+i/(values.length-1)*(w-left-right),y=v=>top+(high-v)/(high-low)*(h-top-bottom),format=v=>v.toLocaleString('en',{maximumFractionDigits:high<10?2:0});let d='',pen=false;values.forEach((v,i)=>{if(!Number.isFinite(v)){pen=false;return;}d+=(pen?'L':'M')+x(i).toFixed(1)+','+y(v).toFixed(1);pen=true;});return `<div class="mini-label">${label} <span>${unit}</span></div><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${label}"><path d="M${left},${top}V${h-bottom}H${w-right}" fill="none" stroke="#c6d3cf"/><path d="${d}" fill="none" stroke="${color}" stroke-width="1.8"/><text x="${left-5}" y="${top+5}" text-anchor="end">${format(high)}</text><text x="${left-5}" y="${h-bottom}" text-anchor="end">${format(low)}</text><text x="${left}" y="${h-5}">${years[0]}</text><text x="${w-right}" y="${h-5}" text-anchor="end">${years.at(-1)}</text></svg>`;}
 function preview(species,id,kind){const el=document.createElement('div');el.className='kelp-mini';const title=document.createElement('strong');title.textContent=names[species]+' · '+(kind==='point'?id:kind==='polygon'?'MOE '+id:id);el.append(title);const body=document.createElement('div');if(kind==='point'){const s=histories[id];body.innerHTML=mini(s.years,s.mass,tr('Individual biomass','كتلة الفرد','個体重量'),'g DW / thallus',colours[species]);}else{const data=spaces[species],r=(kind==='polygon'?data.polygons:data.records)[id];body.innerHTML=mini(data.years,r.series.standing.map(v=>v/1e6),tr('Total standing biomass','إجمالي الكتلة القائمة','総現存量'),'tonnes DW',colours[species])+mini(data.years,r.series.erosion.map(v=>v/1e6),tr('Annual erosion','التآكل السنوي','年間脱落量'),'tonnes DW/year','#a17b43');}el.append(body);const hint=document.createElement('small');hint.textContent=tr('Historical annual values · click for the detailed report','قيم سنوية تاريخية · انقر للتقرير المفصل','過去の年別値・クリックして詳細レポート');el.append(hint);return el;}
 function bind(layer,species,id,kind){layer.bindTooltip(()=>preview(species,id,kind),{className:'kelp-hover',direction:'top',sticky:true,opacity:1,offset:[0,-5]});layer.on('mouseover',e=>{const t=layer.getTooltip(),position=KelpPortal.map.latLngToContainerPoint(e.latlng||layer.getLatLng());t.options.direction=position.y<270?'bottom':'top';t.update();});layer.on('click',()=>{layer.closeTooltip();if(kind==='point')KelpPortal.selectLocation(species,id,true).catch(console.error);else KelpContext.openAreaFor(species,kind==='polygon'?'polygon:'+id:id).catch(console.error);});}
 function labels(){const both=KelpPortal.combined;$('species').previousElementSibling.textContent=both?tr('Report species','نوع التقرير','レポートの種'):PortalLanguage.t('Species');$('bothSpecies').checked=both;$('bothLabel').textContent=tr('Show both species','عرض النوعين معاً','両種を表示');$('mixedKey').innerHTML=`<span><i class="mixed-square"></i> ${names.longissima}</span><span><i class="mixed-circle"></i> ${names.japonica}</span>`;$('mixedHint').textContent=tr('Model coverage · hover for graphs; click for report.','تغطية النموذج · مرّر المؤشر للرسم وانقر للتقرير.','モデル対象域・ホバーでグラフ、クリックで詳細。');document.querySelector('.map-key').hidden=both;for(const id of ['mapYear','mapMetric','playYear'])$(id).disabled=both;if(both){$('mapSpecies').textContent='Saccharina longissima & S. japonica';$('mapRecord').textContent=tr('2,029 stations · historical graph previews','٢٬٠٢٩ محطة · معاينات الرسوم التاريخية','2,029地点・過去の履歴グラフ');}}
 async function redraw(){if(!loaded)return;const stamp=++serial;if(areas)areas.remove();areas=L.layerGroup();if(!KelpPortal.combined){labels();return;}for(const species of ['japonica','longissima']){const data=spaces[species],colour=colours[species];if($('gridLayer').checked)L.geoJSON(data.grids,{pane:'kelpGrid',renderer:gridRenderer,style:{color:colour,weight:species==='longissima'?1.7:1,dashArray:species==='japonica'?'4 3':null,fillColor:colour,fillOpacity:.13},onEachFeature:(f,l)=>bind(l,species,f.properties.grid_2km_id,'grid')}).addTo(areas);if($('moeLayer').checked)L.geoJSON(data.coverage,{pane:'kelpHabitat',renderer:habitatRenderer,style:{color:colour,weight:species==='japonica'?3:1.8,dashArray:species==='japonica'?'5 2':null,fillColor:colour,fillOpacity:species==='japonica'?.3:.52},onEachFeature:(f,l)=>bind(l,species,String(f.properties.polygon_id),'polygon')}).addTo(areas);}if(stamp===serial)areas.addTo(KelpPortal.map);labels();}
 function sync(){if(!loaded)return;if(points)points.remove();if(areas)areas.remove();if(KelpPortal.combined){points.addTo(KelpPortal.map);redraw();}labels();}
 async function setup(){try{const control=document.createElement('div');control.className='mixed-controls';control.innerHTML='<label><input id="bothSpecies" type="checkbox" checked><span id="bothLabel"></span></label><div id="mixedKey"></div><small id="mixedHint"></small>';document.querySelector('.context-layer').prepend(control);$('bothSpecies').onchange=async()=>{await KelpPortal.setCombined($('bothSpecies').checked);KelpContext.redraw();sync();};
   habitatRenderer=L.svg({pane:'kelpHabitat'});gridRenderer=L.svg({pane:'kelpGrid'});KelpPortal.map.createPane('kelpMixedStations');KelpPortal.map.getPane('kelpMixedStations').style.zIndex=400;
   const [long,jap,mass]=await Promise.all([gzip('./data/spatial/longissima.json.gz?v=20261102-polygons-r1'),gzip('./data/spatial/japonica.json.gz?v=20261102-polygons-r1'),gzip('./data/hover-mass.json.gz?v=20261102-both-r1')]);spaces={longissima:long,japonica:jap};histories=mass;points=L.layerGroup();for(const s of KelpPortal.catalogue.stations){let marker;if(s.species==='longissima')marker=L.marker([s.lat,s.lon],{pane:'kelpMixedStations',icon:L.divIcon({className:'mixed-station-square',iconSize:[9,9],iconAnchor:[4.5,4.5]}),keyboard:true,title:names[s.species]+' '+s.id});else marker=L.circleMarker([s.lat,s.lon],{pane:'kelpMixedStations',radius:3.6,color:'#fff',weight:.6,fillColor:colours.japonica,fillOpacity:.85});bind(marker,s.species,s.id,'point');marker.addTo(points);}loaded=true;window.addEventListener('kelpmaprender',sync);window.addEventListener('kelpcombinedchange',()=>{KelpContext.redraw();sync();});window.addEventListener('portallanguagechange',sync);sync();document.documentElement.dataset.mixedReady='true';
  }catch(e){console.error(e);}}
 window.KelpMixed={redraw,get pointLayer(){return points;},get areaLayer(){return areas;},get spaces(){return spaces;},get histories(){return histories;},preview};
 if(document.documentElement.dataset.ready==='true')setup();else window.addEventListener('kelpready',setup,{once:true});
})();
